import{_ as r,C as o,o as s,c as i,ag as t,E as n}from"./chunks/framework.CtWPcAmt.js";const f=JSON.parse('{"title":"Marketplace Landing Page","description":"","frontmatter":{},"headers":[],"relativePath":"storefront/marketplace-landing-page.md","filePath":"storefront/marketplace-landing-page.md","lastUpdated":1787558413000}'),l={name:"storefront/marketplace-landing-page.md"};function g(h,e,p,d,u,c){const a=o("ImagePopup");return s(),i("div",null,[e[0]||(e[0]=t('<h1 id="marketplace-landing-page" tabindex="-1">Marketplace Landing Page <a class="header-anchor" href="#marketplace-landing-page" aria-label="Permalink to &quot;Marketplace Landing Page&quot;">​</a></h1><p>The marketplace landing page is the pitch you make to people who might sell on your platform. It sits at <strong>/marketplace</strong> on your storefront, and every word and picture on it is set from the admin panel — no theming required.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>Where the landing page is configured</li><li>What each section of the page holds</li><li>How the page changes for someone who is already a seller</li></ul></div><h2 id="where-it-s-configured" tabindex="-1">Where it&#39;s configured <a class="header-anchor" href="#where-it-s-configured" aria-label="Permalink to &quot;Where it&#39;s configured&quot;">​</a></h2><p>Go to <strong>Configure → Marketplace → Landing Page</strong>. It has four sections, and they appear on the page in this order: <strong>Banner</strong>, <strong>Highlights</strong>, <strong>Features</strong>, the featured-seller showcase, and <strong>Seller Journey</strong>.</p>',5)),n(a,{src:"/images/marketplace-landing-page/landing-page-config.png",alt:"Landing Page configuration with the Banner, Highlights, Features and Seller Journey sections"}),e[1]||(e[1]=t('<h2 id="banner" tabindex="-1">Banner <a class="header-anchor" href="#banner" aria-label="Permalink to &quot;Banner&quot;">​</a></h2><p>The hero at the top of the page.</p><p><strong>Banner Title</strong> and <strong>Banner Description:</strong> The headline and the sentence under it. <strong>Banner Button Title:</strong> The caption on the call-to-action button. <strong>Banner Image:</strong> The picture beside the text.</p><p>The button leads a visitor to the <a href="/sellers/seller-registration">seller registration form</a>. For a visitor who is <strong>already signed in as a seller</strong>, it becomes <strong>Visit Shop</strong> instead and points at their own store page — so the page never invites an existing seller to sign up again.</p><h2 id="highlights" tabindex="-1">Highlights <a class="header-anchor" href="#highlights" aria-label="Permalink to &quot;Highlights&quot;">​</a></h2><p>Four numbers that make the marketplace look established. Each is a bare value you type; the page supplies the caption:</p><p><strong>Community Count:</strong> Shown as <strong>Seller Community</strong>, with a <strong>+</strong> appended. <strong>Business Hour:</strong> Shown as <strong>Online Business</strong>. <strong>Payment Duration:</strong> Shown as <strong>Days* Payment</strong>. <strong>Serviceable Pincode:</strong> Shown as <strong>Serviceable Pincode</strong>, with a <strong>+</strong> appended.</p><p>Because the captions are fixed and the <strong>+</strong> is added for you, enter only the figure — <strong>500</strong>, not &quot;500+ sellers&quot;.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><p>Why someone should sell with you.</p><p><strong>Feature Title</strong> and <strong>Feature Description:</strong> The section heading and its introduction. <strong>Feature Image:</strong> The image beside the four boxes. <strong>Feature Box 1–4:</strong> Four selling points, each with an <strong>Icon</strong>, a <strong>Title</strong>, and a <strong>Description</strong>.</p><h2 id="featured-sellers" tabindex="-1">Featured sellers <a class="header-anchor" href="#featured-sellers" aria-label="Permalink to &quot;Featured sellers&quot;">​</a></h2><p>Between Features and Seller Journey the page shows <strong>Our Featured Sellers</strong> — real sellers, ranked and picked automatically. Nothing about it is set here; it comes from <strong>Configure → Marketplace → Featured Sellers</strong>, and it only appears when that showcase is switched on. See <a href="/sellers/featured-sellers">Featured Sellers</a>.</p>',13)),n(a,{src:"/images/marketplace-landing-page/landing-page.png",alt:"The marketplace landing page on the storefront, from the banner through to the seller journey"}),e[2]||(e[2]=t('<h2 id="seller-journey" tabindex="-1">Seller Journey <a class="header-anchor" href="#seller-journey" aria-label="Permalink to &quot;Seller Journey&quot;">​</a></h2><p>The last section walks a prospective seller through what joining involves.</p><p><strong>Journey Title</strong> and <strong>Journey Description:</strong> The section heading and its introduction. <strong>Journey Step 1–5:</strong> Five steps, each with an <strong>Icon</strong>, a <strong>Title</strong>, and a <strong>Description</strong>, numbered <strong>Step 1</strong> to <strong>Step 5</strong> on the page.</p><p>You don&#39;t have to fill all five — describe the journey your marketplace actually has.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Write the Seller Journey as the answer to &quot;what happens after I click that button?&quot; — registration, approval, listing a first product, the first order, getting paid. A prospective seller weighing your marketplace against another is looking for exactly that, and it&#39;s the section most marketplaces leave at its defaults.</p></div>',5))])}const _=r(l,[["render",g]]);export{f as __pageData,_ as default};
